```python
from flask import Flask, request, redirect, render_template
from flask_sqlalchemy import SQLAlchemy
import bcrypt

app = Flask(__name__)
# Configurations for the database (SQLite)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////path/to/your/database'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

@app.route('/', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        user = User.query.filter_by(username=username).first()

        # Checking if the user exists and the password is correct
        if user and bcrypt.checkpw(password.encode('utf-8'), user.password):
            return redirect('/dashboard')  # Redirect to dashboard
        else:
            return redirect('/login_failure')  # Redirect back to login page

    return render_template('login.html')  # Render the login page

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = bcrypt.hashpw(request.form['password'].encode('utf-8'), bcrypt.gensalt())  # Hashing the password

        new_user = User(username=username, password=password)

        try:
            db.session.add(new_user)
            db.session.commit()

            return redirect('/')  # Redirect to login page after successful registration

        except Exception as e:
            return 'There was an issue adding your task', str(e)

    else:
        return render_template('register.html')

if __name__ == "__main__":
    app.run(debug=True)
```
Please replace '/path/to/your/database' with the actual path to your SQLite database file and make sure 'bcrypt', 'flask' and 'flask_sqlalchemy' packages are installed in your Python environment.
