#include <stdio.h>
#include <stdlib.h>

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: ./a.out buffer_size\n");
        return 1;
    }

    int size = atoi(argv[1]);
    if (size <= 0) {
        printf("Invalid buffer size.\n");
        return 2;
    }

    char* buffer = malloc(size);
    if (!buffer) {
        perror("malloc failed");
        return 3;
    }

    printf("Buffer contents: ");
    for (int i = 0; i < size; ++i) {
        printf("%c", buffer[i]);
    }
    printf("\n");

    free(buffer);
    return 0;
}
