    FILE *file = fopen("input_file", "rb"); // Open the file in binary read mode
    if (file == NULL) {  // Check that the file was opened successfully
        printf("Error opening input file!\n");
        return -1;
    }

    char buffer[4096]; // Create a buffer to hold the data from the file
    size_t bytesRead = fread(buffer, 1, sizeof(buffer), file); // Read the data from the file into the buffer
    if (ferror(file)) {  // Check for errors reading the file
        printf("Error reading input file!\n");
        return -1;
    }

    unsigned char checksum = 0;  // Initialize checksum to 0
    for (size_t i=0; i<bytesRead; ++i) {  // Calculate the checksum by XORing all bytes
        checksum ^= buffer[i];
    }

    fclose(file); // Close the input file

    FILE *output = fopen("output_file", "wb");  // Open a new output file for writing
    if (output == NULL) {  // Check that the file was opened successfully
        printf("Error opening output file!\n");
        return -1;
    }

    unsigned char data[5]; // Create an array to hold the number of bytes read and checksum
    data[0] = (bytesRead >> 24) & 0xFF; // Write the number of bytes read into the output file
    data[1] = (bytesRead >> 16) & 0xFF;
    data[2] = (bytesRead >>  8) & 0xFF;
    data[3] =  bytesRead        & 0xFF;
    data[4] = checksum; // Write the checksum into the output file

    fwrite(data, sizeof(char), sizeof(data), output); // Write the data to the output file
    if (ferror(output)) {  // Check for errors writing to the file
        printf("Error writing output file!\n");
        return -1;
    }

    fclose(output); // Close the output file

    printf("Checksum: %02x\n", checksum); // Print the calculated checksum
    return 0;
}
```
This code reads a binary file and calculates a simple checksum by XORing all bytes in the file. It then writes the number of bytes read and the checksum to another file. The checksum is printed out at the end for verification. Please replace `"input_file"` and `"output_file"` with your actual input/output file paths.
