from flask import Flask, request, jsonify
import yaml

app = Flask(__name__)

@app.route('/', methods=['POST'])
def receive_request():
    if 'payload' not in request.form:
        return jsonify({"error": "Missing payload parameter."}), 400

    try:
        payload = yaml.safe_load(request.form['payload'])
    except Exception as e:
        return jsonify({"error": f"Invalid YAML in payload: {str(e)}"}), 400

    if 'type' not in payload or payload['type'] is None:
        return jsonify({"error": "Missing type field in the payload."}), 400

    if payload['type'] == 'Create':
        return jsonify({"error": "Cannot process type Create requests."}), 400

    if payload['type'] == 'Update' and payload.get('name') == 'UnsafeDeserialization':
        return jsonify({"error": "Cannot update object with name UnsafeDeserialization."}), 400

    return jsonify({"success": "Request processed successfully!"})

if __name__ == '__main__':
    app.run(port=5000)
```

In this code, the `receive_request` function is called whenever a POST request is made to the root URL of your web application. The payload parameter from the request is then parsed as YAML and processed according to the type field in the payload. 

