int run_id_command(const char *username) {
    // Build the command string
    int bufferSize = snprintf(NULL, 0, "id %s", username) + 1;
    if (bufferSize <= 0) {
        printf("Error building command string\n");
        return -1;
    }
    char *commandStr = malloc(bufferSize);
    snprintf(commandStr, bufferSize, "id %s", username);

    // Run the command
    int retVal = system(commandStr);

    // Free memory
    free(commandStr);

    return WEXITSTATUS(retVal);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <username>\n", argv[0]);
        return 1;
    }

