app = Flask(__name__)
url = "<your_url>"  # Replace with your URL

def check_ping(func):
    def wrapper():
        command = ['ping', '-c', '1', url]
        response = subprocess.call(command, stdout=subprocess.DEVNULL)

        if response == 0:
            pong = "Alive"
        else:
            pong = "Not Alive"

        return func(pong)

    wrapper.__name__ = func.__name__
