['Here's a simple example of how you might implement this in C using the standard library function strtok():

```c
#include <stdio.h>
#include <string.h>

void trim_trailing_whitespace(char *str) {
    char *end;

    // Trim leading space
    while(*str == ' ') str++;

    if(*str == 0)  // All spaces?
        return;

    // Trim trailing space
    end = str + strlen(str) - 1;
    while(end > str && *end == ' ') end--;

    // Write new null terminator character
    *++end = 0;
}

int main(int argc, char **argv){
    if (argc != 2){
        printf("Usage: %s [argument]\n", argv[0]);
        return 1;
    }

    trim_trailing_whitespace(argv[1]);

    printf("%s\n", argv[1]);

    return 0;
}
```
In the above code, we define a function `trim_trailing_whitespace()` that removes trailing spaces from a string. Then, in our main function, we ensure that exactly one command-line argument has been provided and then trim any trailing whitespaces in the argument before printing it out.
